class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new java.util.ArrayList<>();
        boolean[] cols = new boolean[n];
        boolean[] d1 = new boolean[2 * n];
        boolean[] d2 = new boolean[2 * n];
        int[] queens = new int[n];
        solve(0, n, cols, d1, d2, queens, result);
        return result;
    }
    private void solve(int row, int n, boolean[] cols, boolean[] d1, boolean[] d2, int[] queens, List<List<String>> result) {
        if (row == n) {
            List<String> board = new java.util.ArrayList<>();
            for (int q : queens) {
                char[] r = new char[n];
                java.util.Arrays.fill(r, '.');
                r[q] = 'Q';
                board.add(new String(r));
            }
            result.add(board);
            return;
        }
        for (int col = 0; col < n; col++) {
            if (!cols[col] && !d1[row - col + n] && !d2[row + col]) {
                cols[col] = d1[row - col + n] = d2[row + col] = true;
                queens[row] = col;
                solve(row + 1, n, cols, d1, d2, queens, result);
                cols[col] = d1[row - col + n] = d2[row + col] = false;
            }
        }
    }
}
